(()=>{const hero=document.querySelector('.hero'),button=document.getElementById('hero-motion');let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function update(){hero.classList.toggle('motion-paused',paused);button.dataset.en=paused?'Resume motion':'Pause motion';button.dataset.zh=paused?'继续动态':'暂停动态';button.textContent=document.documentElement.lang==='zh-CN'?button.dataset.zh:button.dataset.en;}button.addEventListener('click',()=>{paused=!paused;update();});update();})();
